import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"艮下離上 旅：","description":"京氏易傳 - 艮下離上 旅：","frontmatter":{"title":"艮下離上 旅：","description":"京氏易傳 - 艮下離上 旅："},"headers":[],"relativePath":"classics/jingshi/051.md","filePath":"classics/jingshi/051.md"}'),i={name:"classics/jingshi/051.md"};function r(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"艮下離上-旅",tabindex:"-1"},[l("艮下離上 旅： "),e("a",{class:"header-anchor",href:"#艮下離上-旅","aria-label":"Permalink to “艮下離上 旅：”"},"​")],-1),e("p",null,"陰中見陽，蕩入陽中。陰陽二氣交互，見本象。火居山上，為旅之義。【離為陰，初九為陽；艮為陽，初六為陰。二氣交互，上下見木也。火在上，無止象，旅之義。】《易》曰：“旅人先笑後號咷”。又曰：“得其資斧”。仲尼為旅人，固可知矣。【旅卦為取象，火在山上顯露無止，五行入卦消息，去此遷也。】與艮為飛伏。【丙辰土，己卯木。】其居初六元士，九四諸侯見應。",-1),e("p",null,"建始己酉至甲寅，【秋分，立春。】積算起甲寅至癸丑，週而復始。火土木入離艮。【火木土入卦起積算。】",-1),e("p",null,"五星從位起熒惑，【火星入卦見本象。】壁宿從位降丙辰，【二十八宿，壁宿入旅卦初六丙辰土位上起算。】分氣候三十六。【分三十六數起卦推算。】",-1),e("p",null,"火土同宮，二氣合應，陰陽相對，吉凶分乎陰位。上九陽居宗廟，得喪於易。六五為卦之主，不繫於一兇，其宜也。",-1),e("p",null,"內象適變，蕩陰入陽，巽順於外，進退意器，外象明，應內，為鼎。次降火從風入鼎。【初九之初六，六二之九二，巽為風，離象火，曰鼎。】",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
